  if(profile.volatility===null)missing.add('mode_volatility');
  let economyKnown=initial_economy_diff!==null;
  if(!economyKnown)missing.add('initial_economy_diff');
  const economy=()=>economyKnown?initial_economy_diff+ledger.netDiff:null;
