    for(const [team,mix] of [['blue',styles],['red',opponent_styles]]){
      const absent=[['farm_per_min',values.farm_per_min],['behavior.farm_efficiency',behavior.farm_efficiency]].filter(([,v])=>v===null).map(([k])=>k);
      const reward=absent.length?null:values.farm_per_min*duration/60*behavior.farm_efficiency*(1+mix.farm);
      ids.push(record(at,'farm',team,{reward,status:absent.length?'unknown':'sampled',absent,details:{duration_s:duration,farm_share:mix.farm,parameter_keys:['farm_per_min','behavior.farm_efficiency']}}));
    }
