    const required_behavior=kind==='kill'?['engage_threshold','risk_preference']:['tower','dragon'].includes(kind)?['rotation_tendency']:[];
    let absent=[...(values[chance_key]===null?[chance_key]:[]),...required_behavior.filter(k=>behavior[k]===null).map(k=>`behavior.${k}`)];
